pub struct ApiV1Client<'a> { interface: Interface<'a> }
impl<'a> ApiV1Client<'a> {
    pub fn init(app: &'a App<'_>) -> Result<Self, Error> {
        let interface = Interface::new(app, MODULE_NAME, api_v1_export_name, api_v1_expectation)?;
        Self::checked(interface)
    }
    pub fn optional(app: &'a App<'_>) -> Result<Option<Self>, Error> {
        Interface::optional(app, MODULE_NAME, api_v1_export_name, api_v1_expectation)?.map(Self::checked).transpose()
    }
    fn checked(interface: Interface<'a>) -> Result<Self, Error> {
        if interface.slot_address(32).is_none() { return Err(Error::MissingSlot); }
        if interface.slot_address(40).is_none() { return Err(Error::MissingSlot); }
        Ok(Self { interface })
    }
    /// Berechnet lineare XRGB8888-, ARGB8888- oder R8-Layouts mit gepruefter 64-Bit-Groesse.
    /// # Safety
    /// Keine Allokation; Caller haelt die CPU-Map fuer den gesamten Aufruf.
    /// Blocking: nonblocking; threading: thread_safe; reentrancy: reentrant.
    /// width: value, none, lifetime none, nullable=false.
    /// height: value, none, lifetime none, nullable=false.
    /// format: value, none, lifetime none, nullable=false.
    /// row_alignment: value, none, lifetime none, nullable=false.
    /// output: output, caller_owned, lifetime call, nullable=false.
    pub unsafe fn r#linear_layout(&self, r#width: u32, r#height: u32, r#format: u32, r#row_alignment: u64, r#output: *mut R4GfxLinearLayout) -> i32 {
        let function: ApiV1_linear_layoutFn = unsafe { self.interface.function(32) }.expect("admitted R4L slot");
        unsafe { function(r#width, r#height, r#format, r#row_alignment, r#output) }
    }
    /// Validiert Bildspanne und Rechteck vor dem ersten Schreibzugriff; beruehrt kein Zeilenpadding.
    /// # Safety
    /// Keine Allokation; Caller haelt die CPU-Map fuer den gesamten Aufruf.
    /// Blocking: nonblocking; threading: thread_safe; reentrancy: reentrant.
    /// image: input, borrowed, lifetime call, nullable=false.
    /// rect: input, borrowed, lifetime call, nullable=false.
    /// color: value, none, lifetime none, nullable=false.
    pub unsafe fn r#fill_rect(&self, r#image: *const R4GfxCpuImage, r#rect: *const R4GfxRect, r#color: u32) -> i32 {
        let function: ApiV1_fill_rectFn = unsafe { self.interface.function(40) }.expect("admitted R4L slot");
        unsafe { function(r#image, r#rect, r#color) }
    }
}

